    String medSection = "med";

    @ConfigSection(
            name = "High tier",
            description = "Settings for high value drops",
            position = 2
    )
    String highSection = "high";

    @ConfigSection(
            name = "Insane tier",
            description = "Settings for insane value drops",
            position = 3
    )
    String insaneSection = "insane";

    // ── LOW ──────────────────────────────────────────────────────────────────

    @ConfigItem(
            keyName = "lowEnabled",
            name = "Enable Low tier",
            description = "Toggle Low tier popups on or off",
            section = lowSection,
            position = 0
    )
    default boolean lowEnabled() { return true; }

    @ConfigItem(
            keyName = "lowThreshold",
            name = "GP threshold",
            description = "Minimum item value in GP to trigger a Low notification",
            section = lowSection,
            position = 1
    )
    default int lowThreshold() { return 10_000; }

    @ConfigItem(
            keyName = "lowTitle",
            name = "Header text",
            description = "Text shown in the header bar of the Low tier popup",
            section = lowSection,
            position = 2
    )
    default String lowTitle() { return "Collection log"; }

    @Alpha
    @ConfigItem(
            keyName = "lowColour",
            name = "Border colour",
            description = "Colour of the popup border for Low tier",
            section = lowSection,
            position = 3
    )
    default Color lowColour() { return new Color(140, 140, 140); }

    // ── MEDIUM ────────────────────────────────────────────────────────────────

    @ConfigItem(
            keyName = "medEnabled",
            name = "Enable Medium tier",
            description = "Toggle Medium tier popups on or off",
            section = medSection,
            position = 0
    )
    default boolean medEnabled() { return true; }

    @ConfigItem(
            keyName = "medThreshold",
            name = "GP threshold",
            description = "Minimum item value in GP to trigger a Medium notification",
            section = medSection,
            position = 1
    )
    default int medThreshold() { return 100_000; }

    @ConfigItem(
            keyName = "medTitle",
            name = "Header text",
            description = "Text shown in the header bar of the Medium tier popup",
            section = medSection,
            position = 2
    )
    default String medTitle() { return "Collection log"; }

    @Alpha
    @ConfigItem(
            keyName = "medColour",
            name = "Border colour",
            description = "Colour of the popup border for Medium tier",
            section = medSection,
            position = 3
    )
    default Color medColour() { return new Color(40, 180, 40); }

    // ── HIGH ──────────────────────────────────────────────────────────────────

    @ConfigItem(
            keyName = "highEnabled",
            name = "Enable High tier",
            description = "Toggle High tier popups on or off",
            section = highSection,
            position = 0
    )
    default boolean highEnabled() { return true; }

    @ConfigItem(
            keyName = "highThreshold",
            name = "GP threshold",
            description = "Minimum item value in GP to trigger a High notification",
            section = highSection,
            position = 1
    )
    default int highThreshold() { return 1_000_000; }

    @ConfigItem(
            keyName = "highTitle",
            name = "Header text",
            description = "Text shown in the header bar of the High tier popup",
            section = highSection,
            position = 2
    )
    default String highTitle() { return "Collection log"; }

    @Alpha
    @ConfigItem(
            keyName = "highColour",
            name = "Border colour",
            description = "Colour of the popup border for High tier",
            section = highSection,
            position = 3
    )
    default Color highColour() { return new Color(80, 120, 220); }

    // ── INSANE ────────────────────────────────────────────────────────────────

    @ConfigItem(
            keyName = "insaneEnabled",
            name = "Enable Insane tier",
            description = "Toggle Insane tier popups on or off",
            section = insaneSection,
            position = 0
    )
    default boolean insaneEnabled() { return true; }

    @ConfigItem(
            keyName = "insaneThreshold",
            name = "GP threshold",
            description = "Minimum item value in GP to trigger an Insane notification",
            section = insaneSection,
            position = 1
    )
    default int insaneThreshold() { return 10_000_000; }

    @ConfigItem(
            keyName = "insaneTitle",
            name = "Header text",
            description = "Text shown in the header bar of the Insane tier popup",
            section = insaneSection,
            position = 2
    )
    default String insaneTitle() { return "Collection log"; }

    @Alpha
    @ConfigItem(
            keyName = "insaneColour",
            name = "Border colour",
            description = "Colour of the popup border for Insane tier",
            section = insaneSection,
            position = 3
    )
    default Color insaneColour() { return new Color(180, 80, 180); }
}

package com.lootnotifier;

import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.FontManager;
import net.runelite.api.Client;

import javax.inject.Inject;
import java.awt.*;

public class LootNotifierOverlay extends Overlay
{
    private static final int DISPLAY_DURATION = 5000;
    private static final int PHASE_HORIZ_IN   = 500;
    private static final int PHASE_VERT_IN    = 500;
    private static final int PHASE_VERT_OUT   = 500;
    private static final int PHASE_HORIZ_OUT  = 500;

    private static final int BOX_W   = 260;
    private static final int HDR_H   = 28;
    private static final int BODY_H  = 48;
    private static final int POPUP_H = HDR_H + BODY_H;
    private static final int LINE_H  = 4;

    private static final Color BG_BODY    = new Color(58,  36, 16);
    private static final Color BG_HEADER  = new Color(44,  26,  8);
    private static final Color OUTER_DARK = new Color(26,  14,  4);
    private static final Color TITLE_ORG  = new Color(255, 144, 16);
    private static final Color TEXT_CREAM = new Color(240, 234, 216);

    private final Client client;
    private final LootNotifierConfig config;

    private boolean active    = false;
    private long    shownAt   = 0;
    private String  itemName  = "";
    private String  titleText = "Collection log";
    private Color   accentCol = new Color(200, 168, 96);

    @Inject
    public LootNotifierOverlay(Client client, ItemManager itemManager, LootNotifierConfig config)
    {
        this.client = client;
        this.config = config;
        setPosition(OverlayPosition.TOP_CENTER);
        setLayer(OverlayLayer.ALWAYS_ON_TOP);
    }

    public void showNotification(String itemName, String titleText, Color accentColour)
    {
        this.itemName  = itemName;
        this.titleText = titleText;
        this.accentCol = accentColour;
        this.shownAt   = System.currentTimeMillis();
        this.active    = true;
    }

    private float ease(float t)
    {
        return t * t * (3f - 2f * t);
    }

    @Override
    public Dimension render(Graphics2D g)
    {
        if (!active) return null;

        long elapsed = System.currentTimeMillis() - shownAt;
        if (elapsed > DISPLAY_DURATION)
        {
            active = false;
            return null;
        }

        long holdStart  = PHASE_HORIZ_IN + PHASE_VERT_IN;
        long holdEnd    = DISPLAY_DURATION - PHASE_VERT_OUT - PHASE_HORIZ_OUT;
        long vertOutEnd = DISPLAY_DURATION - PHASE_HORIZ_OUT;

        float horizScale;
        float vertScale;
        boolean showText;

        if (elapsed < PHASE_HORIZ_IN)
        {
            horizScale = ease((float) elapsed / PHASE_HORIZ_IN);
            vertScale  = 0f;
            showText   = false;
        }
        else if (elapsed < holdStart)
        {
            horizScale = 1f;
            vertScale  = ease((float)(elapsed - PHASE_HORIZ_IN) / PHASE_VERT_IN);
            showText   = vertScale > 0.7f;
        }
        else if (elapsed < holdEnd)
        {
            horizScale = 1f;
            vertScale  = 1f;
            showText   = true;
        }
        else if (elapsed < vertOutEnd)
        {
            horizScale = 1f;
            vertScale  = 1f - ease((float)(elapsed - holdEnd) / PHASE_VERT_OUT);
            showText   = vertScale > 0.3f;
        }
        else
        {
            horizScale = 1f - ease((float)(elapsed - vertOutEnd) / PHASE_HORIZ_OUT);
            vertScale  = 0f;
            showText   = false;
        }

        int drawW = Math.max(2, (int)(BOX_W * horizScale));
        int drawH = LINE_H + (int)((POPUP_H - LINE_H) * vertScale);

        int offX = (BOX_W - drawW) / 2;
        int offY = (POPUP_H - drawH) / 2;

        int fx = offX;
        int fy = offY + 8;

        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,      RenderingHints.VALUE_ANTIALIAS_OFF);
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        g2.setClip(fx, fy, drawW, drawH);

        g2.setColor(OUTER_DARK);
        g2.fillRect(fx, fy, BOX_W, POPUP_H);

        g2.setColor(accentCol);
        g2.fillRect(fx + 4, fy + 4, BOX_W - 8, POPUP_H - 8);

        g2.setColor(BG_BODY);
        g2.fillRect(fx + 5, fy + 5, BOX_W - 10, POPUP_H - 10);

        g2.setColor(BG_HEADER);
        g2.fillRect(fx + 5, fy + 5, BOX_W - 10, HDR_H - 2);

        g2.setColor(OUTER_DARK);
        g2.fillRect(fx + 5, fy + HDR_H - 2, BOX_W - 10, 2);

        g2.setColor(accentCol);
        g2.fillRect(fx + 5, fy + HDR_H, BOX_W - 10, 1);

        if (showText)
        {
            float textAlpha = Math.min(1f, (vertScale - 0.7f) / 0.3f);
            textAlpha = Math.max(0f, textAlpha);
            g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, textAlpha));

            g2.setFont(FontManager.getRunescapeBoldFont());
            FontMetrics fm = g2.getFontMetrics();
            int titleX = fx + (BOX_W - fm.stringWidth(titleText)) / 2;
            int titleY = fy + HDR_H - 6;
            g2.setColor(Color.BLACK);
            g2.drawString(titleText, titleX + 1, titleY + 1);
            g2.setColor(TITLE_ORG);
            g2.drawString(titleText, titleX, titleY);

            g2.setFont(FontManager.getRunescapeBoldFont());
            fm = g2.getFontMetrics();
            int itemX = fx + (BOX_W - fm.stringWidth(itemName)) / 2;
            int itemY = fy + HDR_H + 26;
            g2.setColor(Color.BLACK);
            g2.drawString(itemName, itemX + 1, itemY + 1);
            g2.setColor(TEXT_CREAM);
            g2.drawString(itemName, itemX, itemY);
        }

        g2.dispose();
        return new Dimension(BOX_W, POPUP_H + 16);
    }
}

package com.lootnotifier;

import com.google.inject.Provides;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.Client;
import net.runelite.api.ItemComposition;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.events.PlayerLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStack;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import javax.inject.Inject;
import java.awt.Color;
import java.util.Collection;

@Slf4j
@PluginDescriptor(
        name = "Loot Notifier",
        description = "Shows a collection log style popup for drops above your GP thresholds",
        tags = {"loot", "drops", "notification", "collection", "log"}
)
public class LootNotifierPlugin extends Plugin
{
    @Inject private Client client;
    @Inject private ItemManager itemManager;
    @Inject private OverlayManager overlayManager;
    @Inject private LootNotifierConfig config;
    @Inject private LootNotifierOverlay overlay;

    @Override
    protected void startUp()
    {
        overlayManager.add(overlay);
        log.info("Loot Notifier started");
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        log.info("Loot Notifier stopped");
    }

    @Provides
    LootNotifierConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(LootNotifierConfig.class);
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event)
    {
        processLoot(event.getItems());
    }

    @Subscribe
    public void onPlayerLootReceived(PlayerLootReceived event)
    {
        processLoot(event.getItems());
    }

    private void processLoot(Collection<ItemStack> items)
    {
        long bestPrice    = 0;
        String bestName   = null;
        TierMatch bestMatch = null;

        for (ItemStack stack : items)
        {
            int itemId   = stack.getId();
            int quantity = stack.getQuantity();
            long gePrice = (long) itemManager.getItemPrice(itemId) * quantity;

            TierMatch match = getTier(gePrice);
            if (match == null) continue;

            if (gePrice > bestPrice)
            {
                bestPrice = gePrice;
                bestMatch = match;
                ItemComposition comp = itemManager.getItemComposition(itemId);
                bestName = comp.getName() + (quantity > 1 ? " x" + quantity : "");
            }
        }

        if (bestMatch != null)
        {
            overlay.showNotification(bestName, bestMatch.title, bestMatch.accent);
        }
    }

    private TierMatch getTier(long price)
    {
        if (config.insaneEnabled() && price >= config.insaneThreshold())
            return new TierMatch(config.insaneTitle(), config.insaneColour());

        if (config.highEnabled() && price >= config.highThreshold())
            return new TierMatch(config.highTitle(), config.highColour());

        if (config.medEnabled() && price >= config.medThreshold())
            return new TierMatch(config.medTitle(), config.medColour());

        if (config.lowEnabled() && price >= config.lowThreshold())
            return new TierMatch(config.lowTitle(), config.lowColour());

        return null;
    }

    private static class TierMatch
    {
        final String title;
        final Color  accent;
        TierMatch(String title, Color accent)
        { this.title = title; this.accent = accent; }
    }
}

